阅读下面的主进程片段，把 4 个空缺处的事件名或取值补全（事件名不带引号，取值不区分大小写）：
```js
const win = new BrowserWindow({
  show: false,
  webPreferences: {
    preload: path.join(__dirname, 'preload.js'),
    // 要让 contextBridge 的隔离语义真正生效，这一项必须是：(1)______
    contextIsolation: '(1)______'
  }
});
// 避免首屏白屏闪烁：等到 (2)______ 事件再显示窗口
win.on('(2)______', () => win.show());
// 窗口彻底销毁后清掉缓存引用，防止访问已销毁对象
win.on('(3)______', () => { windows.delete(win); });

if (!app.requestSingleInstanceLock()) {
  app.quit();
} else {
  // 第二个实例启动时，持锁实例在该事件回调里收到它的 argv
  app.on('(4)______', (argv, workingDirectory) => focusOrCreate(argv));
}
```
